#include <Aevrynd/AnimationGraph3D.h>
#include <algorithm>
#include <cmath>
#include <limits>
#include <new>
namespace Aevrynd { namespace {
bool FiniteTransform(const JointTransform3D& v){const float a[]={v.translation.x,v.translation.y,v.translation.z,v.rotation.x,v.rotation.y,v.rotation.z,v.scale.x,v.scale.y,v.scale.z,v.quaternion.x,v.quaternion.y,v.quaternion.z,v.quaternion.w};return std::all_of(std::begin(a),std::end(a),[](float x){return std::isfinite(x);})&&v.scale.x!=0&&v.scale.y!=0&&v.scale.z!=0;}
bool FiniteMatrix(const Matrix4& m){for(size_t r=0;r<4;++r)for(size_t c=0;c<4;++c)if(!std::isfinite(m[r][c]))return false;return true;}
size_t PoseBytes(const AnimationPose3D& p){return p.localTransforms.capacity()*sizeof(JointTransform3D)+p.globalMatrices.capacity()*sizeof(Matrix4);}
size_t ClipBytes(const AnimationClip3D& clip){size_t bytes=clip.tracks.capacity()*sizeof(AnimationTrack3D);for(const auto& track:clip.tracks)bytes+=track.keyframes.capacity()*sizeof(AnimationKeyframe3D);return bytes;}
}
bool AnimationGraph3D::Initialize(const Skeleton3D& skeleton,SkeletonCompatibilityId3D compatibility,std::span<const AnimationGraphState3D> states,AnimationGraphError3D* error){auto fail=[&](AnimationGraphError3D e){if(error)*error=e;return false;};if(!skeleton.Valid()||std::any_of(skeleton.joints.begin(),skeleton.joints.end(),[](const auto& j){return!FiniteTransform(j.bindTransform);}))return fail(AnimationGraphError3D::InvalidSkeleton);if(skeleton.joints.size()>256)return fail(AnimationGraphError3D::Limit);if(!compatibility)return fail(AnimationGraphError3D::UnknownCompatibility);if(states.empty()||states.size()>MaximumStates)return fail(AnimationGraphError3D::Limit);AnimationGraph3D candidate;candidate.compatibility_=compatibility;candidate.jointCount_=skeleton.joints.size();candidate.skeletonDefinition_=skeleton;candidate.stateCount_=states.size();try{for(size_t s=0;s<states.size();++s){if(states[s].name.empty()||states[s].samples.empty()||states[s].samples.size()>MaximumSamplesPerState)return fail(AnimationGraphError3D::InvalidState);candidate.states_[s].name=std::string(states[s].name);candidate.states_[s].count=states[s].samples.size();float previous=-std::numeric_limits<float>::infinity();for(size_t i=0;i<states[s].samples.size();++i){const auto sample=states[s].samples[i];if(!std::isfinite(sample.parameter)||!sample.clip||!sample.clip->Valid(skeleton))return fail(AnimationGraphError3D::InvalidSample);if(sample.parameter<=previous)return fail(AnimationGraphError3D::DuplicateSample);previous=sample.parameter;candidate.states_[s].samples[i]={sample.parameter,*sample.clip};}}for(AnimationPose3D* p:{&candidate.outputScratch_,&candidate.baseScratch_,&candidate.sampleA_,&candidate.sampleB_,&candidate.transitionFrom_,&candidate.layerPose_}){p->localTransforms.reserve(candidate.jointCount_);p->globalMatrices.reserve(candidate.jointCount_);}}catch(const std::bad_alloc&){return fail(AnimationGraphError3D::Limit);}*this=std::move(candidate);if(error)*error={};return true;}
bool AnimationGraph3D::SetState(size_t state,float duration,bool sync){if(state>=stateCount_||!std::isfinite(duration)||duration<0)return false;if(state==state_&&!transitioning_)return true;transitionSnapshotValid_=baseScratch_.localTransforms.size()==jointCount_;if(transitionSnapshotValid_)transitionFrom_=baseScratch_;if(transitioning_)++stats_.interruptions;if(!sync)phase_=0;state_=state;transitionDuration_=duration;transitionElapsed_=0;transitioning_=duration>0&&transitionSnapshotValid_;++stats_.transitions;return true;}
bool AnimationGraph3D::SetNormalizedPhase(float value)noexcept{if(!std::isfinite(value))return false;phase_=value-std::floor(value);if(phase_<0)phase_+=1;return true;}
bool AnimationGraph3D::SetUpperBodyLayer(AnimationGraphLayer3D layer,AnimationGraphError3D* error){if(!layer.clip||!layer.clip->Valid(skeletonDefinition_)||layer.jointWeights.size()!=jointCount_||!std::isfinite(layer.weight)||layer.weight<0||layer.weight>1||std::any_of(layer.jointWeights.begin(),layer.jointWeights.end(),[](float x){return!std::isfinite(x)||x<0||x>1;})){if(error)*error=AnimationGraphError3D::InvalidLayer;return false;}try{AnimationClip3D clip=*layer.clip;std::vector<float> weights(layer.jointWeights.begin(),layer.jointWeights.end());layerClip_=std::move(clip);layerWeights_=std::move(weights);}catch(const std::bad_alloc&){if(error)*error=AnimationGraphError3D::Limit;return false;}layerWeight_=layer.weight;layerEnabled_=true;if(error)*error={};return true;}
float AnimationGraph3D::StateDuration(size_t state)const noexcept{const auto& s=states_[state];if(s.count==1||parameter_<=s.samples[0].parameter)return s.samples[0].clip.duration;if(parameter_>=s.samples[s.count-1].parameter)return s.samples[s.count-1].clip.duration;size_t u=1;while(u<s.count&&parameter_>s.samples[u].parameter)++u;const auto& a=s.samples[u-1];const auto& b=s.samples[u];const float t=(parameter_-a.parameter)/(b.parameter-a.parameter);return a.clip.duration+(b.clip.duration-a.clip.duration)*t;}
void AnimationGraph3D::Update(float dt)noexcept{if(!std::isfinite(dt)||dt<0||!stateCount_)return;const float duration=StateDuration(state_);if(std::isfinite(duration)&&duration>0){phase_=std::fmod(phase_+dt/duration,1.f);if(phase_<0)phase_+=1;}if(transitioning_){transitionElapsed_=(std::min)(transitionDuration_,transitionElapsed_+dt);if(transitionElapsed_>=transitionDuration_)transitioning_=false;}}
float AnimationGraph3D::TransitionAmount()const noexcept{return!transitioning_||transitionDuration_<=0?1.f:Clamp(transitionElapsed_/transitionDuration_,0.f,1.f);}
bool AnimationGraph3D::SampleState(const Skeleton3D& skeleton,size_t state,float phase,AnimationPose3D& output,Matrix4 root){const auto& s=states_[state];auto sample=[&](const OwnedSample& v,AnimationPose3D& p){SampleAnimationClipInto(skeleton,v.clip,phase*v.clip.duration,p,root);};if(s.count==1||parameter_<=s.samples[0].parameter){sample(s.samples[0],output);return true;}if(parameter_>=s.samples[s.count-1].parameter){sample(s.samples[s.count-1],output);return true;}size_t u=1;while(u<s.count&&parameter_>s.samples[u].parameter)++u;const auto& a=s.samples[u-1];const auto& b=s.samples[u];sample(a,sampleA_);sample(b,sampleB_);BlendAnimationPosesInto(skeleton,sampleA_,sampleB_,(parameter_-a.parameter)/(b.parameter-a.parameter),output,root);return true;}
bool AnimationGraph3D::EvaluateInto(const Skeleton3D& skeleton,SkeletonCompatibilityId3D compatibility,AnimationPose3D& output,Matrix4 root){if(!compatibility_||compatibility!=compatibility_||!skeleton.Valid()||skeleton.joints.size()!=jointCount_||jointCount_>256||!FiniteMatrix(root)){++stats_.rejectedEvaluations;return false;}SampleState(skeleton,state_,phase_,baseScratch_,root);if(transitioning_&&transitionSnapshotValid_)BlendAnimationPosesInto(skeleton,transitionFrom_,baseScratch_,TransitionAmount(),baseScratch_,root);outputScratch_=baseScratch_;if(layerEnabled_&&layerWeight_>0){SampleAnimationClipInto(skeleton,layerClip_,phase_*layerClip_.duration,layerPose_,root);std::array<bool,256> tracked{};for(const auto& track:layerClip_.tracks)if(track.joint<tracked.size())tracked[track.joint]=true;for(size_t j=0;j<jointCount_;++j){const float w=tracked[j]?layerWeights_[j]*layerWeight_:0;if(w>0)outputScratch_.localTransforms[j]=InterpolateJointTransform(outputScratch_.localTransforms[j],layerPose_.localTransforms[j],w);}BuildAnimationPoseGlobalMatrices3D(skeleton,outputScratch_,root);}for(const auto& t:outputScratch_.localTransforms)if(!FiniteTransform(t)){++stats_.rejectedEvaluations;return false;}for(const auto& matrix:outputScratch_.globalMatrices)if(!FiniteMatrix(matrix)){++stats_.rejectedEvaluations;return false;}output=outputScratch_;++stats_.evaluations;return true;}
void AnimationGraph3D::Reset()noexcept{stateCount_=jointCount_=state_=0;compatibility_={};parameter_=phase_=transitionDuration_=transitionElapsed_=0;transitioning_=transitionSnapshotValid_=false;layerEnabled_=false;layerWeight_=0;layerWeights_.clear();stats_={};}
ReusableMemoryStats AnimationGraph3D::MemoryStats()const noexcept{size_t bytes=PoseBytes(outputScratch_)+PoseBytes(baseScratch_)+PoseBytes(sampleA_)+PoseBytes(sampleB_)+PoseBytes(transitionFrom_)+PoseBytes(layerPose_)+layerWeights_.capacity()*sizeof(float)+skeletonDefinition_.joints.capacity()*sizeof(SkeletonJoint3D)+ClipBytes(layerClip_);for(const auto& state:states_){bytes+=state.name.capacity();for(size_t sample=0;sample<state.count;++sample)bytes+=ClipBytes(state.samples[sample].clip);}return{bytes,stateCount_?0:bytes,lastReleasedBytes_,trimCount_};}
size_t AnimationGraph3D::TrimUnusedMemory(){if(stateCount_)return 0;const size_t before=MemoryStats().retainedCapacityBytes;for(AnimationPose3D* p:{&outputScratch_,&baseScratch_,&sampleA_,&sampleB_,&transitionFrom_,&layerPose_}){std::vector<JointTransform3D>().swap(p->localTransforms);std::vector<Matrix4>().swap(p->globalMatrices);}std::vector<float>().swap(layerWeights_);std::vector<SkeletonJoint3D>().swap(skeletonDefinition_.joints);layerClip_={};for(auto& state:states_){std::string().swap(state.name);for(auto& sample:state.samples)sample.clip={};state.count=0;}lastReleasedBytes_=before;++trimCount_;return before;}
}
